using System.Linq;
using Newtonsoft.Json.Linq;
using UnityEngine;
public sealed class BlockApp:MonoBehaviour
{
 BlockConnection connection;BlockWorld world;JObject content;string address="ws://localhost:3001/ws",nickname="Neighbor",code="",district="garden",page="Explore",account="shared";Vector2 scroll;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Boot(){if(FindFirstObjectByType<BlockApp>()==null)new GameObject("OUR BLOCK").AddComponent<BlockApp>();}
 void Awake(){var config=Resources.Load<TextAsset>("ServerConfig");if(config!=null)address=(string)JObject.Parse(config.text)["server"];content=JObject.Parse(Resources.Load<TextAsset>("Content").text);connection=gameObject.AddComponent<BlockConnection>();world=gameObject.AddComponent<BlockWorld>();world.Connection=connection;world.Content=content;}
 void Action(string type,string target=null,JObject extra=null){var f=extra??new JObject();if(target!=null)f["target"]=target;connection.Act(type,f);}
 void Button(string label,string type,string target=null,JObject extra=null){if(GUILayout.Button(label,GUILayout.MinHeight(30)))Action(type,target,extra);}
 void Walk(string id){district=id;var d=content["districts"].First(x=>(string)x["id"]==id);Action("move",null,new JObject{["x"]=d["x"],["z"]=(float)d["z"]+3});}
 void OnGUI(){GUI.skin.label.wordWrap=true;GUI.skin.button.wordWrap=true;GUILayout.BeginArea(new Rect(12,12,350,Screen.height-24),GUI.skin.box);GUILayout.Label("OUR BLOCK · learn by doing",GUI.skin.box);
 if(connection.State==null||!connection.Connected){GUILayout.Label("Server");address=GUILayout.TextField(address);GUILayout.Label("Nickname");nickname=GUILayout.TextField(nickname,24);GUILayout.Label("Town code (empty creates a town)");code=GUILayout.TextField(code);GUI.enabled=!connection.Busy;if(GUILayout.Button("Join / create town"))connection.Connect(address,nickname,code,false);if(GUILayout.Button("Recover saved seat"))connection.Connect(address,nickname,code,true);GUI.enabled=true;GUILayout.Label(connection.Message);GUILayout.EndArea();return;}
 var s=connection.State;var me=s["players"].First(x=>(string)x["id"]==(string)s["you"]);GUILayout.Label($"Town {s["code"]} · Day {s["day"]} · Shared {s["funds"]} · Yours {me["money"]}");GUILayout.BeginHorizontal();foreach(var title in new[]{"Explore","Projects","Bag","Ledger"})if(GUILayout.Button(title))page=title;GUILayout.EndHorizontal();GUILayout.Label(connection.Message);world.ReducedMotion=GUILayout.Toggle(world.ReducedMotion,"Reduced motion");scroll=GUILayout.BeginScrollView(scroll);
 if((bool)s["review"]){GUILayout.Label("Day complete. Review your ledger.");Button("Start next day","next");}
 foreach(var q in s["pending"]){GUILayout.Label($"{q["target"]}: {q["cost"]} shared credits requested");if((string)q["by"]!=(string)me["id"])Button("Approve","approve",(string)q["id"]);Button("Cancel","cancel",(string)q["id"]);}
 foreach(var d in content["districts"])if(GUILayout.Button("Walk to "+d["name"]))Walk((string)d["id"]);
 if(page=="Explore"){GUILayout.Label("District: "+district);foreach(var a in content["activities"].Where(x=>(string)x["district"]==district)){GUILayout.Label((string)a["description"]);Button((string)a["name"],"activity",(string)a["id"]);}account=GUILayout.Toggle(account=="personal","Pay with personal earnings")?"personal":"shared";
 foreach(var o in content["offers"].Where(x=>(string)x["district"]==district)){GUILayout.Label($"{o["name"]} · {o["price"]} credits. {o["detail"]}");Button("Buy","buy",(string)o["id"],new JObject{["account"]=account});if((int?)me["bag"][(string)o["item"]]>=(int)o["qty"])Button("Return unused","refund",(string)o["id"]);}
 foreach(var u in content["upgrades"].Where(x=>(string)x["district"]==district)){GUILayout.Label($"{u["name"]}: {u["cost"]}. {u["detail"]}");if(!s["upgrades"].Any(x=>(string)x==(string)u["id"]))Button("Improve","upgrade",(string)u["id"],new JObject{["account"]=account});}
 if(district=="hall"){GUILayout.Label("Bill: "+s["bill"]);Button("Pay bill","bill",null,new JObject{["account"]=account});Button("Work for bill relief","negotiate-bill");Button("Return kitchen","return-kitchen");}}
 if(page=="Projects")foreach(var pr in content["projects"]){string id=(string)pr["id"];var c=s["contracts"][id];GUILayout.Label($"{pr["name"]} · Reward {pr["reward"]}\n{pr["requirements"]}\nDue in {pr["deadline"]} days. Cancel without fee.");if((int?)c?["variant"]==1)GUILayout.Label(id=="garden"?"Also bring a protective pad.":id=="market"?"Bring TWO packed orders.":"Bring TWO repaired stools.");if((string)c?["status"]=="active"){Button("Complete","complete",id);Button("Cancel","abandon",id);}else Button("Accept / repeat","accept",id);}
 if(page=="Bag"){foreach(var i in ((JObject)me["bag"]).Properties()){GUILayout.Label(i.Name+" × "+i.Value);Button("Store one at Home","transfer",null,new JObject{["item"]=i.Name,["qty"]=1,["direction"]="store"});foreach(var p in s["players"].Where(x=>(string)x["id"]!=(string)me["id"]))Button("Give to "+p["name"],"give",null,new JObject{["item"]=i.Name,["qty"]=1,["player"]=p["id"]});Button("EMBER: store one at Home","companion",null,new JObject{["item"]=i.Name});}GUILayout.Label("Shared storage");foreach(var i in ((JObject)s["storage"]).Properties())Button($"Take {i.Name} (stored: {i.Value})","transfer",null,new JObject{["item"]=i.Name,["qty"]=1,["direction"]="take"});Button("Contribute earnings at Home","deposit",null,new JObject{["qty"]=me["money"]});GUILayout.Label("Evidence notebook");foreach(var e in s["evidence"]){var a=content["activities"].FirstOrDefault(x=>(string)x["evidence"]==(string)e);if(a!=null)GUILayout.Label((string)a["observation"]);}}
 if(page=="Ledger")foreach(var r in s["ledger"].Reverse())GUILayout.Label($"Day {r["day"]} · {r["text"]}: {r["amount"]} ({r["account"]})");GUILayout.Space(15);GUILayout.Label("Neighborhood radio");foreach(var p in content["pings"])Button((string)p,"ping",district,new JObject{["text"]=p});foreach(var p in s["radio"].Reverse()){GUILayout.Label($"{p["by"]}: {p["text"]} at {p["district"]}");Button("On it","ack",(string)p["id"]);}GUILayout.EndScrollView();GUILayout.EndArea();}
}
